use azums::{quickstart, NewEvent};
use serde_json::json; #[tokio::main]
async fn main() -> anyhow::Result<()> { let client = quickstart("memory").await?; let orders_stream = client.stream("orders"); // 1. Publish Event let seq = orders_stream.publish("order_created", json!({ "order_id": "ord_1001", "amount": 250.00, "customer_id": "cust_42" })).await?; println!("Appended event at sequence_no: {seq}"); // 2. Read Events (from sequence offset 0) let events = orders_stream.read_events(0, 100).await?; for event in &events { println!("Event #{}: {} => {:?}", event.sequence_no, event.event_type, event.payload_json); } // 3. Acknowledge Consumer Group Offset orders_stream.ack("analytics_group", seq).await?; // 4. Fetch Consumer Group Status let group_info = orders_stream.consumer_group_info().await?; for cg in &group_info { println!("Group: {}, Last Acked Seq: {}", cg.consumer_group, cg.last_acked_seq); } Ok(())
}

