Batch job leasing uses a Common Table Expression (CTE) to atomically select, lock, and transition jobs from queued to running: WITH candidates AS ( SELECT id FROM jobs WHERE dataset_id = $1 AND queue = $2 AND status = 'queued' AND run_at <= now() ORDER BY priority DESC, run_at ASC, created_at ASC FOR UPDATE SKIP LOCKED LIMIT $3
),
leased AS ( UPDATE jobs j SET status = 'running', locked_by = $4, locked_at = now(), lock_expires_at = now() + ($5::int * interval '1 second'), updated_at = now() FROM candidates c WHERE j.id = c.id RETURNING j.*
)
SELECT * FROM leased
ORDER BY priority DESC, run_at ASC, created_at ASC;

