async fn main() -> anyhow::Result<()> { // Automatically connects to local database or DATABASE_URL and runs migrations let flow = quickstart("memory").await?; // Enqueue a job with a JSON payload flow.enqueue(Job::new("greet", serde_json::json!({"name": "World"}))).await?; // Register async job handler flow.register_handler("greet", |job| async move { println!("Hello, {}!", job.payload["name"]); Ok(()) }).await; // Run until queue is empty flow.run_until_empty().await?; Ok(())
}

