In applications with high completed job volumes, partitioning by status isolates active queued and running jobs into a tiny subtable, completely insulating worker leasing queries from historical succeeded or dlq records. -- 1. Create parent table partitioned by job lifecycle status
CREATE TABLE jobs_by_status ( id UUID NOT NULL DEFAULT gen_random_uuid(), queue TEXT NOT NULL, job_type TEXT NOT NULL, payload_json JSONB NOT NULL DEFAULT '{}'::jsonb, run_at TIMESTAMPTZ NOT NULL DEFAULT now(), status TEXT NOT NULL DEFAULT 'queued', priority INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (status, id)
) PARTITION BY LIST (status); -- 2. Create dedicated status partitions
CREATE TABLE jobs_active PARTITION OF jobs_by_status FOR VALUES IN ('queued', 'running'); CREATE TABLE jobs_completed PARTITION OF jobs_by_status FOR VALUES IN ('succeeded'); CREATE TABLE jobs_failed PARTITION OF jobs_by_status FOR VALUES IN ('failed', 'dlq', 'canceled');

